/** Public entry point — the only module consumers/docs should import from. */

export { useDataGridPagination, type UseDataGridPaginationClientOptions, type UseDataGridPaginationResult, type DataGridPaginationControls } from "./use-data-grid-pagination";
export { useDataGridServerPager, type UseDataGridServerPagerOptions } from "./use-data-grid-server-pager";
export { useDataGridPager, type UseDataGridPagerOptions } from "./use-data-grid-pager";
export {
  DataGridPaginationBar,
  type DataGridPaginationBarProps,
  DataGridPaginationRange,
  DataGridPaginationPageSize,
  DataGridPaginationFirst,
  DataGridPaginationPrev,
  DataGridPaginationPages,
  type DataGridPaginationPagesProps,
  DataGridPaginationNext,
  DataGridPaginationLast,
} from "./pagination-footer";

export { useStashedPager } from "./pager-stash";

"use client";

import { useMemo, useState } from "react";
import { clampPage, DEFAULT_PAGE_SIZES, pageCount, pageRange } from "./pagination-math";

/** What `<DataGridPaginationBar {...pager} />` spreads.  */
export type DataGridPaginationControls = {
  page: number;
  /** Pages the user can reach. With an unknown `totalRowCount` it is `page`, plus 1 while `hasMore`. */
  pageCount: number;
  pageSize: number;
  pageSizeOptions: readonly number[];
  /** Row count across all pages; `null` when the server sends no count. */
  totalRowCount: number | null;
  /** True when a page after the current one exists. */
  hasMore: boolean;
  /** What a page counts: `"groups"` while the grid is grouped (a page holds top-level groups, `totalRowCount` counts them), else `"rows"`. Default `"rows"`. */
  unit?: "rows" | "groups";
  onPageChange: (page: number) => void;
  onPageSizeChange: (pageSize: number) => void;
};

/** Options of {@link useDataGridPagination}. */
export type UseDataGridPaginationClientOptions<TData> = {
  data: readonly TData[];
  /** First page size while `pageSize` is not controlled. Default: the first of `pageSizeOptions`. */
  defaultPageSize?: number;
  /** Controls the page size; pair it with `onPageSizeChange`. */
  pageSize?: number;
  /** Page sizes the footer offers. Default 10, 25, 50, 100. */
  pageSizeOptions?: readonly number[];
  /** First page while `page` is not controlled. Default 1. */
  defaultPage?: number;
  /** Controls the current page; pair it with `onPageChange`. A page outside `[1, pageCount]` shows the nearest page. */
  page?: number;
  onPageChange?: (page: number) => void;
  /** Fires after a page-size change with the new size. */
  onPageSizeChange?: (pageSize: number) => void;
};

/**
 * Options of {@link useDataGridServerPager} (`UseDataGridServerPagerOptions`): you own `page` and `pageSize` and fetch each page's rows. The hook computes the page window
 * and the pager. `totalRowCount` is `null` when the server does not count rows; `hasMore` then says whether another page exists.
 * A `page` outside `[1, pageCount]` calls `onPageChange` once with the clamped page, never while `totalRowCount` is 0.
 * With a `null` count only a page below 1 is lifted. For a source that fetches, sorts, and filters for you, use `useDataGridServerRows`.
 */
export type UseDataGridPaginationServerOptions = {
  page: number;
  pageSize: number;
  totalRowCount: number | null;
  /** Read only when `totalRowCount` is `null`. Default `false`. */
  hasMore?: boolean;
  onPageChange: (page: number) => void;
  pageSizeOptions?: readonly number[];
  onPageSizeChange?: (pageSize: number) => void;
};

export type UseDataGridPaginationResult<TData> = {
  /** The current page's slice of `data`. */
  pageData: readonly TData[];
  pager: DataGridPaginationControls;
};

/**
 * Slices a dataset into pages and builds the pager, for a list that lives outside the grid. Page and page size are uncontrolled
 * unless you pass `page` or `pageSize` with their change callbacks.
 *
 * To page the rows of a grid, set `pageSize` on `DataGridProvider` instead and read the pager with `useDataGridPager`: the grid
 * then sorts, filters, and totals all of `data` and shows one page of the result.
 */
export function useDataGridPagination<TData>(options: UseDataGridPaginationClientOptions<TData>): UseDataGridPaginationResult<TData> {
  return useClientPagination<TData>(options);
}

function useClientPagination<TData>(options: UseDataGridPaginationClientOptions<TData>): UseDataGridPaginationResult<TData> {
  const { data, pageSizeOptions = DEFAULT_PAGE_SIZES, onPageChange: onPageChangeProp, onPageSizeChange: onPageSizeChangeProp } = options;
  const [internalPageSize, setInternalPageSize] = useState(options.defaultPageSize ?? pageSizeOptions[0] ?? DEFAULT_PAGE_SIZES[0]);
  const [internalPage, setInternalPage] = useState(options.defaultPage ?? 1);

  const pageSize = options.pageSize ?? internalPageSize;
  const controlledPage = options.page;
  const controlled = controlledPage !== undefined;
  const rawPage = controlled ? controlledPage : internalPage;
  const page = clampPage(rawPage, data.length, pageSize);

  const setPage = (next: number, sizeForClamp: number = pageSize) => {
    const clamped = clampPage(next, data.length, sizeForClamp);
    if (!controlled) setInternalPage(clamped);
    onPageChangeProp?.(clamped);
  };

  const pageData = useMemo(() => {
    const { start, end } = pageRange(page, pageSize, data.length);
    return data.slice(start, end);
  }, [data, page, pageSize]);

  const pager: DataGridPaginationControls = {
    page,
    pageCount: pageCount(data.length, pageSize),
    pageSize,
    pageSizeOptions,
    totalRowCount: data.length,
    hasMore: page < pageCount(data.length, pageSize),
    onPageChange: setPage,
    onPageSizeChange: (nextSize) => {
      setInternalPageSize(nextSize);
      onPageSizeChangeProp?.(nextSize);
      // keep the same first-visible row across a page-size change
      const firstRow = (page - 1) * pageSize;
      setPage(Math.floor(firstRow / nextSize) + 1, nextSize);
    },
  };

  return { pageData, pager };
}

"use client";

import { useEffect, useMemo, useRef } from "react";
import type { DataGridPlugin } from "@/registry/default/components/data-grid/data-grid";
import { usePagerStashPlugin } from "./pager-stash";
import { clampPage, DEFAULT_PAGE_SIZES, pageCount } from "./pagination-math";
import type { DataGridPaginationControls, UseDataGridPaginationServerOptions } from "./use-data-grid-pagination";

export type UseDataGridServerPagerOptions = UseDataGridPaginationServerOptions & {
  /** What a page counts. Default `"rows"`. */
  unit?: "rows" | "groups";
};

const NO_PAGE_SIZE_OPTIONS: readonly number[] = [];
const noop = () => {};

/** Result of {@link useDataGridServerPager}. */
export type UseDataGridServerPagerResult = {
  pager: DataGridPaginationControls;
  /**
   * Spread onto `DataGridProvider`: `totalRowCount` puts sort and filter in server mode, and `plugins` lets a `DataGridPaginationBar` without props
   * read this pager. A `plugins` prop after the spread replaces it; add your plugins to `gridProps.plugins` instead.
   */
  gridProps: { totalRowCount: number | null; plugins: readonly DataGridPlugin[] };
};

/** The pager for rows your own data layer fetches page by page. Spread `pager` onto `DataGridPaginationBar`, or `gridProps` onto `DataGridProvider` for a bar without props. Without `onPageSizeChange` the bar hides the page-size select. */
export function useDataGridServerPager(options: UseDataGridServerPagerOptions): UseDataGridServerPagerResult {
  const { page, pageSize, totalRowCount, onPageChange, pageSizeOptions = DEFAULT_PAGE_SIZES, onPageSizeChange, unit } = options;
  const clampedPage = clampPage(page, totalRowCount, pageSize);
  const lastPage = totalRowCount === null ? null : pageCount(totalRowCount, pageSize);
  const hasMore = lastPage === null ? options.hasMore === true : clampedPage < lastPage;

  // The ref keeps the reconcile fire to one per (page, clamped) pair — no re-fire when the consumer
  // ignores the callback or passes an unstable onPageChange.
  const firedRef = useRef<{ page: number; clamped: number } | null>(null);
  useEffect(() => {
    if (totalRowCount !== null && totalRowCount <= 0) return;
    const clamped = clampPage(page, totalRowCount, pageSize);
    if (clamped === page) {
      firedRef.current = null;
      return;
    }
    const fired = firedRef.current;
    if (fired && fired.page === page && fired.clamped === clamped) return;
    firedRef.current = { page, clamped };
    onPageChange(clamped);
  }, [page, totalRowCount, pageSize, onPageChange]);

  const pager: DataGridPaginationControls = {
    page: clampedPage,
    pageCount: lastPage ?? clampedPage + (hasMore ? 1 : 0),
    pageSize,
    pageSizeOptions: onPageSizeChange ? pageSizeOptions : NO_PAGE_SIZE_OPTIONS,
    totalRowCount,
    hasMore,
    ...(unit === "groups" ? { unit } : {}),
    onPageChange,
    onPageSizeChange: onPageSizeChange ?? noop,
  };
  const stash = usePagerStashPlugin(pager);
  const gridProps = useMemo(() => ({ totalRowCount, plugins: [stash] }), [totalRowCount, stash]);
  return { pager, gridProps };
}

"use client";

import { useEffect, useState, useSyncExternalStore } from "react";
import type { DataGridPlugin } from "@/registry/default/components/data-grid/data-grid";
import { useDataGridStoreApi } from "@/registry/default/components/data-grid/data-grid-sdk";
import type { DataGridPaginationControls } from "./use-data-grid-pagination";

type PagerBox = {
  pager: DataGridPaginationControls;
  listeners: Set<() => void>;
  onRead: () => void;
};

/** A server hook sets a function under this key on the stash plugin to learn that a bar read the pager. */
const PAGER_READ = Symbol.for("gridcn.pager-read");

const boxes = new WeakMap<object, PagerBox>();
const registryListeners = new Set<() => void>();

const notify = (listeners: Set<() => void>) => listeners.forEach((listener) => listener());

const subscribeRegistry = (listener: () => void) => {
  registryListeners.add(listener);
  return () => void registryListeners.delete(listener);
};

function publish(box: PagerBox, pager: DataGridPaginationControls) {
  if (box.pager === pager) return;
  box.pager = pager;
  notify(box.listeners);
}

function StashMount({ box }: { box: PagerBox }): null {
  const store = useDataGridStoreApi();
  useEffect(() => {
    boxes.set(store, box);
    notify(registryListeners);
    return () => {
      if (boxes.get(store) === box) boxes.delete(store);
      notify(registryListeners);
    };
  }, [store, box]);
  return null;
}

/** A plugin that hands `pager` to every bare `DataGridPaginationBar` under the grid that mounts it. */
export function usePagerStashPlugin(pager: DataGridPaginationControls): DataGridPlugin {
  const [{ box, plugin }] = useState(() => {
    const box: PagerBox = { pager, listeners: new Set(), onRead: () => (plugin as Record<symbol, (() => void) | undefined>)[PAGER_READ]?.() };
    const plugin: DataGridPlugin = { name: "server-pager", Mount: () => <StashMount box={box} /> };
    return { box, plugin };
  });
  useEffect(() => publish(box, pager), [box, pager]);
  return plugin;
}

/** The pager that a server hook stashed for the enclosing grid, or `null`. */
export function useStashedPager(): DataGridPaginationControls | null {
  const store = useDataGridStoreApi();
  const box = useSyncExternalStore(
    subscribeRegistry,
    () => boxes.get(store) ?? null,
    () => null,
  );
  const pager = useSyncExternalStore(
    (listener) => {
      box?.listeners.add(listener);
      return () => void box?.listeners.delete(listener);
    },
    () => box?.pager ?? null,
    () => null,
  );
  useEffect(() => box?.onRead(), [box]);
  return pager;
}

"use client";

import { useEffect, useMemo } from "react";
import { useDataGridApi } from "@/registry/default/components/data-grid/data-grid";
import { fullViewOf, effectivePage, pageUnitsOf, useDataGridSelector } from "@/registry/default/components/data-grid/data-grid-sdk";
import { DEFAULT_PAGE_SIZES, pageCount } from "./pagination-math";
import type { DataGridPaginationControls } from "./use-data-grid-pagination";

/** Options of {@link useDataGridPager}. */
export type UseDataGridPagerOptions = {
  /** Page sizes the footer offers. Default: the provider's `pageSizeOptions`, else 10, 25, 50, 100. */
  pageSizeOptions?: readonly number[];
};

/**
 * The pager of a grid that pages its view, as `{ pager }` like `useDataGridServerPager` (`pageSize` on `DataGridProvider`). Call it under the provider and spread the result onto
 * `DataGridPaginationBar`, or build your own controls from it. The total counts every row the sort and filter leave, not one page.
 * A grid without `pageSize` reads as one page that holds every row.
 */
export function useDataGridPager(options: UseDataGridPagerOptions = {}): { pager: DataGridPaginationControls } {
  const providerSizes = useDataGridSelector<unknown, readonly number[] | undefined>((s) => s.pageSizeOptions);
  const pageSizeOptions = options.pageSizeOptions ?? providerSizes ?? DEFAULT_PAGE_SIZES;
  const { actions } = useDataGridApi();
  const requestedPage = useDataGridSelector<unknown, number>((s) => s.page);
  const configuredSize = useDataGridSelector<unknown, number | null>((s) => s.pageSize);
  const total = useDataGridSelector<unknown, number>((s) => pageUnitsOf(fullViewOf(s.viewIndex)));
  const unit = useDataGridSelector<unknown, "rows" | "groups">((s) => (s.groupLayout ? "groups" : "rows"));
  const pageSize = configuredSize ?? Math.max(1, total);
  const page = effectivePage(requestedPage, total, pageSize);

  useEffect(() => {
    if (configuredSize !== null && total > 0 && page !== requestedPage) actions.setPage(page);
  }, [actions, configuredSize, page, requestedPage]);

  const pager = useMemo<DataGridPaginationControls>(() => {
    const lastPage = pageCount(total, pageSize);
    return {
      page,
      pageCount: lastPage,
      pageSize,
      pageSizeOptions,
      totalRowCount: total,
      hasMore: page < lastPage,
      ...(unit === "groups" ? { unit } : {}),
      onPageChange: (next) => actions.setPage(next),
      onPageSizeChange: (next) => actions.setPageSize(next),
    };
  }, [actions, page, pageSize, pageSizeOptions, total, unit]);
  return { pager };
}

"use client";

import { createContext, use, useEffect, useRef, type ReactNode } from "react";
import { ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { DEFAULT_LABELS, type DataGridPaginationLabels } from "@/registry/default/components/data-grid/data-grid";
import { GRID_ATTR, isDev, mergeLabelLayers, useDataGridSelector, useOptionalDataGridLabels } from "@/registry/default/components/data-grid/data-grid-sdk";
import type { DataGridPaginationControls } from "./use-data-grid-pagination";
import { useDataGridPager } from "./use-data-grid-pager";
import { useStashedPager } from "./pager-stash";
import { DEFAULT_PAGE_SIZES, pageWindow } from "./pagination-math";

/** Default window size for {@link DataGridPaginationPages} when its `windowSize` prop is omitted. */
const DEFAULT_PAGE_WINDOW_SIZE = 5;

type PaginationBarContextValue = {
  controls: DataGridPaginationControls;
  labels: DataGridPaginationLabels;
};

const PaginationBarContext = createContext<PaginationBarContextValue | null>(null);

/** Resolves the enclosing bar's context, throwing with a clear message outside {@link DataGridPaginationBar}. */
function usePaginationBarContext(part: string): PaginationBarContextValue {
  const ctx = use(PaginationBarContext);
  if (!ctx) {
    throw new Error(`[data-grid-pagination] <${part} /> must be used inside a <DataGridPaginationBar>.`);
  }
  return ctx;
}

/** Props for {@link DataGridPaginationBar}. */
type BarControls = Omit<DataGridPaginationControls, "pageSizeOptions">;

export type DataGridPaginationBarProps = (BarControls | { [K in keyof BarControls]?: never }) & {
  /** Page sizes the select offers. Default: the controls' own list (10, 25, 50, 100 inside a provider). */
  pageSizeOptions?: readonly number[];
  className?: string;
  /**
   * i18n override for this footer's strings, merged key by key over the enclosing grid's
   * `labels.pagination` (the built-in defaults outside a `DataGridProvider`).
   */
  labels?: Partial<DataGridPaginationLabels>;
  /** How many numbered page buttons the default layout shows at once (forwarded to `DataGridPaginationPages`; ignored with `children`). Default 5. */
  windowSize?: number;
  /** Custom composition of parts; omit to render the default layout (range, page-size, first/prev/pages/next/last). */
  children?: ReactNode;
};

/**
 * Pagination footer bar: provides the shared `DataGridPaginationControls` + merged labels to its
 * children via context, shadcn-`Pagination` style. With no `children` it renders the default
 * layout so the common case stays a one-liner; pass `children` built from the parts below
 * (`DataGridPaginationRange`, `DataGridPaginationPageSize`, `DataGridPaginationFirst`,
 * `DataGridPaginationPrev`, `DataGridPaginationPages`, `DataGridPaginationNext`,
 * `DataGridPaginationLast`) for a custom arrangement.
 *
 * Works identically for every source: spread the `DataGridPaginationControls` of
 * `useDataGridPagination`, `useDataGridServerPager`, `useDataGridPager`, or `useDataGridServerRows`,
 * or pass no controls inside a `DataGridProvider` with `pageSize` to read the grid's own pager.
 * Inside a grid that spreads `useDataGridServerRows` `gridProps` (or `useDataGridServerPager` `gridProps`) a bar without controls reads that hook's pager.
 */
export function DataGridPaginationBar(props: DataGridPaginationBarProps): ReactNode {
  return props.page === undefined ? <ProviderPaginationBar {...props} /> : <PaginationBarView {...props} controls={{ ...(props as BarControls), pageSizeOptions: props.pageSizeOptions ?? DEFAULT_PAGE_SIZES }} />;
}

/** The bar of a grid without controls on the bar: the pager comes from the server hook of the enclosing `DataGridProvider`, else from the grid's own paging. */
function ProviderPaginationBar(props: DataGridPaginationBarProps): ReactNode {
  const { pager: viewPager } = useDataGridPager(props.pageSizeOptions ? { pageSizeOptions: props.pageSizeOptions } : {});
  const stashed = useStashedPager();
  const controls = stashed ? { ...stashed, pageSizeOptions: stashed.pageSizeOptions.length > 0 ? (props.pageSizeOptions ?? stashed.pageSizeOptions) : stashed.pageSizeOptions } : viewPager;
  const serverRows = useDataGridSelector<unknown, boolean>((s) => s.totalRowCount !== undefined && s.pageSize === null) && !stashed;
  const warned = useRef(false);
  useEffect(() => {
    if (!serverRows || warned.current || !isDev()) return;
    // the server pager registers in the commit's effects; warn only if none has arrived by the next task
    const timer = setTimeout(() => {
      warned.current = true;
      warnServerBar();
    }, 0);
    return () => clearTimeout(timer);
  }, [serverRows]);
  return <PaginationBarView {...props} controls={controls} />;
}

const warnServerBar = () =>
  console.warn("[data-grid-pagination] this grid's rows come from a server; spread `pager.gridProps` (from `useDataGridServerPager`) onto DataGridProvider, or spread `pager` onto DataGridPaginationBar");

function PaginationBarView(props: DataGridPaginationBarProps & { controls: DataGridPaginationControls }): ReactNode {
  const { controls, className, labels: labelsOverride, windowSize, children } = props;
  const gridLabels = useOptionalDataGridLabels();
  const labels = mergeLabelLayers<DataGridPaginationLabels>(DEFAULT_LABELS.pagination, gridLabels?.pagination, labelsOverride);

  return (
    <PaginationBarContext value={{ controls, labels }}>
      <div {...{ [GRID_ATTR.pagination]: "" }} className={cn("flex flex-wrap items-center justify-between gap-2 border-t border-border bg-background px-2 py-1.5", className)}>
        {children ?? (
          <>
            <DataGridPaginationRange />
            <div className="flex flex-wrap items-center gap-3">
              <DataGridPaginationPageSize />
              <div className="flex items-center gap-1">
                <DataGridPaginationFirst />
                <DataGridPaginationPrev />
                <DataGridPaginationPages windowSize={windowSize} />
                <DataGridPaginationNext />
                <DataGridPaginationLast />
              </div>
            </div>
          </>
        )}
      </div>
    </PaginationBarContext>
  );
}

/** The "x–y of z" range label, {@link DataGridPaginationLabels.rangeEmpty} when `totalRowCount` is 0, or {@link DataGridPaginationLabels.rangeUnknown} ("Page 3") when `totalRowCount` is `null`. */
export function DataGridPaginationRange(): ReactNode {
  const { controls, labels } = usePaginationBarContext("DataGridPaginationRange");
  const { page, pageSize, totalRowCount, unit } = controls;
  if (totalRowCount === null) return <span className="text-xs tabular-nums text-muted-foreground">{labels.rangeUnknown(page)}</span>;
  const from = totalRowCount === 0 ? 0 : (page - 1) * pageSize + 1;
  const to = Math.min(page * pageSize, totalRowCount);

  return <span className="text-xs tabular-nums text-muted-foreground">{totalRowCount === 0 ? labels.rangeEmpty : (unit === "groups" ? labels.rangeGroups : labels.range)(from, to, totalRowCount)}</span>;
}

/** The rows-per-page `Select`. */
export function DataGridPaginationPageSize(): ReactNode {
  const { controls, labels } = usePaginationBarContext("DataGridPaginationPageSize");
  const { pageSize, pageSizeOptions, onPageSizeChange, unit } = controls;
  if (pageSizeOptions.length === 0) return null;

  return (
    <Select value={String(pageSize)} onValueChange={(value) => onPageSizeChange(Number(value))}>
      <SelectTrigger className="h-8 w-fit" aria-label={unit === "groups" ? labels.pageSizeGroupsAriaLabel : labels.pageSizeAriaLabel}>
        {/* explicit label lookup: SelectValue only resolves a mounted SelectItem's label, which the popup content isn't until first opened. */}
        <SelectValue>{(value: string) => labels.pageSizeOption(Number(value))}</SelectValue>
      </SelectTrigger>
      <SelectContent>
        {pageSizeOptions.map((size) => (
          <SelectItem key={size} value={String(size)}>
            {labels.pageSizeOption(size)}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
}

/** Jump to page 1; disabled on page 1. */
export function DataGridPaginationFirst(): ReactNode {
  const { controls, labels } = usePaginationBarContext("DataGridPaginationFirst");
  const { page, onPageChange } = controls;

  return (
    <Button type="button" variant="ghost" size="icon-sm" aria-label={labels.firstPage} disabled={page <= 1} onClick={() => onPageChange(1)}>
      <ChevronsLeft className="rtl:rotate-180" />
    </Button>
  );
}

/** Page − 1; disabled on page 1. */
export function DataGridPaginationPrev(): ReactNode {
  const { controls, labels } = usePaginationBarContext("DataGridPaginationPrev");
  const { page, onPageChange } = controls;

  return (
    <Button type="button" variant="ghost" size="icon-sm" aria-label={labels.previousPage} disabled={page <= 1} onClick={() => onPageChange(page - 1)}>
      <ChevronLeft className="rtl:rotate-180" />
    </Button>
  );
}

/** Props for {@link DataGridPaginationPages}. */
export type DataGridPaginationPagesProps = {
  /** How many numbered page buttons to show at once (see {@link pageWindow}). Default 5. */
  windowSize?: number;
};

/** The sliding numbered page buttons — the only source of page numbers in the composable layout. */
export function DataGridPaginationPages(props: DataGridPaginationPagesProps): ReactNode {
  const { windowSize = DEFAULT_PAGE_WINDOW_SIZE } = props;
  const { controls, labels } = usePaginationBarContext("DataGridPaginationPages");
  const { page, pageCount, onPageChange } = controls;
  const pages = pageWindow(page, pageCount, windowSize);

  return (
    <>
      {pages.map((p) => (
        <Button
          key={p}
          type="button"
          variant={p === page ? "default" : "ghost"}
          size="icon-sm"
          aria-label={labels.pageAriaLabel(p)}
          aria-current={p === page ? "page" : undefined}
          onClick={() => onPageChange(p)}
        >
          {p}
        </Button>
      ))}
    </>
  );
}

/** Page + 1; disabled when no next page exists. */
export function DataGridPaginationNext(): ReactNode {
  const { controls, labels } = usePaginationBarContext("DataGridPaginationNext");
  const { page, hasMore, onPageChange } = controls;

  return (
    <Button type="button" variant="ghost" size="icon-sm" aria-label={labels.nextPage} disabled={!hasMore} onClick={() => onPageChange(page + 1)}>
      <ChevronRight className="rtl:rotate-180" />
    </Button>
  );
}

/** Jump to the last page; disabled on the last page and while the count is unknown. */
export function DataGridPaginationLast(): ReactNode {
  const { controls, labels } = usePaginationBarContext("DataGridPaginationLast");
  const { page, pageCount, onPageChange } = controls;

  return (
    <Button type="button" variant="ghost" size="icon-sm" aria-label={labels.lastPage} disabled={controls.totalRowCount === null || page >= pageCount} onClick={() => onPageChange(pageCount)}>
      <ChevronsRight className="rtl:rotate-180" />
    </Button>
  );
}

/** Page sizes the footer select offers when `pageSizeOptions` is not given. */
export const DEFAULT_PAGE_SIZES = [10, 25, 50, 100] as const;

/** Total pages for `total` rows at `pageSize` per page — at least 1 even when `total` is 0 (an empty grid still shows "page 1"). */
export function pageCount(total: number, pageSize: number): number {
  if (pageSize <= 0) return 1;
  return Math.max(1, Math.ceil(total / pageSize));
}

/**
 * Clamps `page` (1-based) into `[1, pageCount(total, pageSize)]` — the fallback when data shrinks or pageSize changes out from under the current page.
 * An unknown `total` (`null`) clamps the lower bound only.
 */
export function clampPage(page: number, total: number | null, pageSize: number): number {
  const lowerBounded = Math.max(1, Math.floor(page));
  return total === null ? lowerBounded : Math.min(lowerBounded, pageCount(total, pageSize));
}

/** Half-open `[start, end)` row range for `page` (1-based) at `pageSize`, clamped to `total`. */
export function pageRange(page: number, pageSize: number, total: number): { start: number; end: number } {
  const start = Math.min((page - 1) * pageSize, total);
  const end = Math.min(start + pageSize, total);
  return { start, end };
}

/**
 * Sliding page numbers for the footer, e.g. page 7 of 20 with windowSize 5 -> [5,6,7,8,9].
 * The window slides to stay centered on `page` but clamps at both ends so it never runs past
 * `[1, pageCount]` or shows fewer than `windowSize` numbers when there's room for that many.
 */
export function pageWindow(page: number, pageCount: number, windowSize: number): number[] {
  if (pageCount <= 0) return [];
  const size = Math.max(1, Math.min(windowSize, pageCount));
  let start = page - Math.floor(size / 2);
  start = Math.max(1, Math.min(start, pageCount - size + 1));
  return Array.from({ length: size }, (_, i) => start + i);
}
